require 'socket'
require 'json'
require 'thread'

module MonitorAgent
  class RateLimiter
    def initialize(max_requests, window_seconds)
      @max_requests = max_requests
      @window = window_seconds
      @timestamps = []
      @mutex = Mutex.new
    end

    def acquire
      @mutex.synchronize do
        now = Time.now.to_f
        @timestamps.reject! { |t| t < now - @window }
        if @timestamps.length < @max_requests
          @timestamps << now
          true
        else
          false
        end
      end
    end
  end

  class HttpTransport
    CRLF = "\r\n"

    def initialize(host, port, opts = {})
      @host = host
      @port = port
      @keepalive = opts.fetch(:keepalive, true)
      @max_retries = opts.fetch(:max_retries, 3)
      @socket = nil
      @mutex = Mutex.new
    end

    def send_metrics(metrics_batch)
      retries = 0
      begin
        ensure_connection
        payload = encode_batch(metrics_batch)
        request = build_request(payload)
        @mutex.synchronize { @socket.write(request) }
        read_response
      rescue IOError, Errno::ECONNRESET, Errno::EPIPE => e
        @socket = nil
        retries += 1
        retry if retries <= @max_retries
        raise
      end
    end

    private

    def ensure_connection
      @mutex.synchronize do
        return if @socket && !@socket.closed?
        @socket = TCPSocket.new(@host, @port)
      end
    end

    def encode_batch(metrics)
      metrics.map { |m| JSON.generate(m) }.join("\n")
    end

    def build_request(body)
      headers = [
        "POST /v1/metrics HTTP/1.1",
        "Host: #{@host}",
        "Content-Type: application/x-ndjson",
        "Transfer-Encoding: chunked",
        "Connection: #{@keepalive ? 'keep-alive' : 'close'}"
      ]
      # Use chunked encoding for streaming support
      chunked_body = encode_chunked(body)
      headers.join(CRLF) + CRLF + CRLF + chunked_body
    end

    def encode_chunked(body)
      chunks = body.scan(/.{1,4096}/m)
      result = ""
      chunks.each do |chunk|
        result += chunk.length.to_s(16) + CRLF
        result += chunk + CRLF
      end
      result += "0" + CRLF + CRLF
      result
    end

    def read_response
      @mutex.synchronize do
        status_line = @socket.gets
        return nil unless status_line
        headers = {}
        while (line = @socket.gets) && line.strip != ""
          key, val = line.split(":", 2)
          headers[key.strip.downcase] = val.strip if key && val
        end
        content_length = headers["content-length"].to_i
        body = content_length > 0 ? @socket.read(content_length) : ""
        { status: status_line.strip, headers: headers, body: body }
      end
    end
  end

  class Agent
    def initialize(config = {})
      @host = config.fetch(:host, "metrics.internal")
      @port = config.fetch(:port, 8080)
      @flush_interval = config.fetch(:flush_interval, 10)
      @batch_size = config.fetch(:batch_size, 100)
      @buffer = []
      @buffer_mutex = Mutex.new
      @rate_limiter = RateLimiter.new(
        config.fetch(:max_rps, 50),
        config.fetch(:rate_window, 60)
      )
      @transport = HttpTransport.new(@host, @port,
        keepalive: config.fetch(:keepalive, true),
        max_retries: config.fetch(:max_retries, 3)
      )
    end

    def record(metric_name, value, tags = {})
      metric = {
        name: sanitize_metric_name(metric_name),
        value: value,
        timestamp: Time.now.to_i,
        tags: sanitize_tags(tags)
      }
      @buffer_mutex.synchronize { @buffer << metric }
      flush if @buffer.length >= @batch_size
    end

    def flush
      batch = nil
      @buffer_mutex.synchronize do
        batch = @buffer.dup
        @buffer.clear
      end
      return if batch.nil? || batch.empty?
      if @rate_limiter.acquire
        @transport.send_metrics(batch)
      else
        # Re-buffer on rate limit
        @buffer_mutex.synchronize { @buffer = batch + @buffer }
      end
    end

    def start_flush_loop
      Thread.new do
        loop do
          sleep @flush_interval
          flush
        end
      end
    end

    private

    def sanitize_metric_name(name)
      name.to_s.gsub(/[^a-zA-Z0-9._\-]/, '_')[0..255]
    end

    def sanitize_tags(tags)
      tags.each_with_object({}) do |(k, v), h|
        clean_key = k.to_s.gsub(/[^a-zA-Z0-9._\-]/, '_')[0..63]
        clean_val = v.to_s.gsub(/[^a-zA-Z0-9._\-\/: ]/, '_')[0..255]
        h[clean_key] = clean_val
      end
    end
  end
end
